using UnityEngine;
using UnityEditor;

public class CleanPlayerPrefab
{
    public static object Main()
    {
        string prefabPath = "Assets/Prefab/Player.prefab";
        GameObject prefabRoot = PrefabUtility.LoadPrefabContents(prefabPath);
        if (prefabRoot == null) return "Prefab not found";

        int removedMissing = GameObjectUtility.RemoveMonoBehavioursWithMissingScript(prefabRoot);

        Transform mainCanvas = null;
        foreach (Transform child in prefabRoot.transform)
        {
            if (child.name == "MainCanvas")
            {
                mainCanvas = child;
                break;
            }
        }
        bool removedCanvas = false;
        if (mainCanvas != null)
        {
            Object.DestroyImmediate(mainCanvas.gameObject);
            removedCanvas = true;
        }

        PrefabUtility.SaveAsPrefabAsset(prefabRoot, prefabPath);
        PrefabUtility.UnloadPrefabContents(prefabRoot);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        return $"Cleaned Player.prefab: Missing scripts removed={removedMissing}, MainCanvas removed={removedCanvas}";
    }
}
